import java.util.*;

public class Main {
    static class Pkt {
        int x, y;
        Pkt(int x, int y) { this.x = x; this.y = y; }
    }
    static class Kraw {
        int a, res;
        Kraw(int a, int res) { this.a = a; this.res = res; }
    }

    static int n, t;
    static int[] dx = {-1, 0, 1, 0, 0};
    static int[] dy = {0, 1, 0, -1, 0};

    static boolean Ok(int x, int y) {
        return x >= 0 && x < n && y >= 0 && y < n;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        t = sc.nextInt();
        sc.nextLine(); // consume newline
        String[] nau = new String[n];
        String[] pom = new String[n];
        for (int i = 0; i < n; ++i) nau[i] = sc.nextLine();
        for (int i = 0; i < n; ++i) pom[i] = sc.nextLine();

        int[][] odl = new int[n][n];
        for (int i = 0; i < n; ++i) Arrays.fill(odl[i], 1000);

        Pkt start = null;
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j)
                if (nau[i].charAt(j) == 'Z')
                    start = new Pkt(i, j);

        Queue<Pkt> Q = new LinkedList<>();
        odl[start.x][start.y] = 0;
        Q.add(start);
        while (!Q.isEmpty()) {
            Pkt akt = Q.poll();
            for (int i = 0; i < 4; ++i) {
                Pkt nowy = new Pkt(akt.x + dx[i], akt.y + dy[i]);
                if (Ok(nowy.x, nowy.y) && nau[nowy.x].charAt(nowy.y) >= '0' && nau[nowy.x].charAt(nowy.y) <= '9' && odl[nowy.x][nowy.y] == 1000) {
                    odl[nowy.x][nowy.y] = odl[akt.x][akt.y] + 1;
                    Q.add(nowy);
                }
            }
        }

        boolean[][][][][] moge = new boolean[60][10][10][10][10];
        // initialize to false (default)
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                for (int k = 0; k < 5; ++k) {
                    int l = i + dx[k], m = j + dy[k];
                    if (Ok(l, m) && nau[i].charAt(j) >= '0' && nau[i].charAt(j) <= '9' && nau[l].charAt(m) >= '0' && nau[l].charAt(m) <= '9')
                        moge[0][i][j][l][m] = true;
                }
            }
        }

        for (int i = 0; i <= t - 2; ++i) {
            for (int j = 0; j < n; ++j) {
                for (int k = 0; k < n; ++k) {
                    for (int l = 0; l < n; ++l) {
                        for (int m = 0; m < n; ++m) {
                            if (!moge[i][j][k][l][m]) continue;
                            for (int o = 0; o < 5; ++o) {
                                int p = l + dx[o], r = m + dy[o];
                                if (Ok(p, r) && nau[p].charAt(r) >= '0' && nau[p].charAt(r) <= '9' && odl[l][m] >= i + 2 && odl[p][r] >= i + 2)
                                    moge[i + 1][j][k][p][r] = true;
                            }
                        }
                    }
                }
            }
        }

        List<Pkt> a = new ArrayList<>();
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j)
                if (nau[i].charAt(j) >= '0' && nau[i].charAt(j) <= '9')
                    a.add(new Pkt(i, j));

        int wie = 2 * a.size() + 2;
        List<List<Kraw>> G = new ArrayList<>(wie);
        for (int i = 0; i < wie; ++i) G.add(new ArrayList<>());

        for (int i = 0; i < a.size(); ++i) {
            G.get(0).add(new Kraw(i + 1, nau[a.get(i).x].charAt(a.get(i).y) - '0'));
            G.get(i + 1).add(new Kraw(0, 0));
            G.get(a.size() + 1 + i).add(new Kraw(wie - 1, pom[a.get(i).x].charAt(a.get(i).y) - '0'));
            G.get(wie - 1).add(new Kraw(a.size() + 1 + i, 0));
        }

        for (int i = 0; i < a.size(); ++i) {
            for (int j = 0; j < a.size(); ++j) {
                boolean ok = false;
                for (int k = 0; k <= t - 1; ++k)
                    ok |= moge[k][a.get(i).x][a.get(i).y][a.get(j).x][a.get(j).y];
                if (ok) {
                    G.get(i + 1).add(new Kraw(a.size() + 1 + j, 1000));
                    G.get(a.size() + 1 + j).add(new Kraw(i + 1, 0));
                }
            }
        }

        int odp = 0;
        while (true) {
            boolean[] odw = new boolean[wie];
            int[] pop = new int[wie];
            Arrays.fill(pop, -1);
            Queue<Integer> Q2 = new LinkedList<>();
            odw[0] = true;
            Q2.add(0);
            while (!Q2.isEmpty()) {
                int akt = Q2.poll();
                for (Kraw kraw : G.get(akt)) {
                    if (!odw[kraw.a] && kraw.res > 0) {
                        Q2.add(kraw.a);
                        pop[kraw.a] = akt;
                        odw[kraw.a] = true;
                    }
                }
            }
            if (pop[wie - 1] == -1) break;

            List<Integer> path = new ArrayList<>();
            int akt = wie - 1;
            while (akt != -1) {
                path.add(akt);
                akt = pop[akt];
            }
            Collections.reverse(path);

            int flow = 1000;
            for (int i = 0; i < path.size() - 1; ++i) {
                int u = path.get(i);
                int v = path.get(i + 1);
                for (Kraw kraw : G.get(u)) {
                    if (kraw.a == v) {
                        flow = Math.min(flow, kraw.res);
                        break;
                    }
                }
            }
            odp += flow;
            for (int i = 0; i < path.size() - 1; ++i) {
                int u = path.get(i);
                int v = path.get(i + 1);
                for (Kraw kraw : G.get(u)) {
                    if (kraw.a == v) {
                        kraw.res -= flow;
                        break;
                    }
                }
            }
            for (int i = 1; i < path.size(); ++i) {
                int u = path.get(i);
                int v = path.get(i - 1);
                for (Kraw kraw : G.get(u)) {
                    if (kraw.a == v) {
                        kraw.res += flow;
                        break;
                    }
                }
            }
        }
        System.out.println(odp);
        sc.close();
    }
}
